"""Render facts to a LaTeX macro file and keep a lock of the values last built (design 4.4, 6.8)."""
from __future__ import annotations

import json
from pathlib import Path

from ..project import Project
from .model import FactSet

HEADER = (
    "% GENERATED by `ah facts build`. Do not edit. Source: {src}\n"
    "% An undefined key prints (??) and writes a warning to the log, so it cannot pass silently.\n"
)

PREAMBLE = r"""\providecommand{\fact}[1]{%
  \ifcsname fact:#1\endcsname\csname fact:#1\endcsname
  \else\textbf{(??)}\GenericWarning{}{AH warning: undefined fact #1}\fi}
"""


def render_macros(project: Project, fs: FactSet) -> str:
    out = [HEADER.format(src=project.cfg["facts"]), PREAMBLE]
    for fid in sorted(fs.facts):
        f = fs.facts[fid]
        for var in sorted(f.variants):
            out.append(f"\\expandafter\\def\\csname fact:{fid}.{var}\\endcsname{{{f.variants[var]['tex']}}}")
        dv = f.default_variant()
        out.append(f"\\expandafter\\def\\csname fact:{fid}\\endcsname{{{f.variants[dv]['tex']}}}")
    return "\n".join(out) + "\n"


def lock_path(project: Project) -> Path:
    return project.state_dir / "facts.lock.json"


def to_lock(fs: FactSet) -> dict:
    return {fid: {"variants": {v: d["plain"] for v, d in f.variants.items()}, "inputs": f.inputs}
            for fid, f in sorted(fs.facts.items())}


def read_lock(project: Project) -> dict | None:
    p = lock_path(project)
    return json.loads(p.read_text()) if p.exists() else None


def diff_lock(old: dict | None, new: dict) -> dict:
    """Facts added, removed, or whose variant values changed since the last build."""
    if old is None:
        return {"added": sorted(new), "removed": [], "changed": {}}
    changed = {}
    for fid in new:
        if fid in old and old[fid]["variants"] != new[fid]["variants"]:
            changed[fid] = {v: (old[fid]["variants"].get(v), new[fid]["variants"].get(v))
                            for v in sorted(set(old[fid]["variants"]) | set(new[fid]["variants"]))
                            if old[fid]["variants"].get(v) != new[fid]["variants"].get(v)}
    return {"added": sorted(set(new) - set(old)), "removed": sorted(set(old) - set(new)), "changed": changed}


def write_build(project: Project, fs: FactSet) -> dict:
    """Write macros + lock. Returns the lock diff so callers can run the sweep on changes."""
    new = to_lock(fs)
    d = diff_lock(read_lock(project), new)
    m = project.macros_file()
    m.parent.mkdir(parents=True, exist_ok=True)
    m.write_text(render_macros(project, fs))
    project.state_dir.mkdir(parents=True, exist_ok=True)
    lock_path(project).write_text(json.dumps(new, indent=1, sort_keys=True))
    return d
